"""
Pagine di autenticazione (variante server).
_LOGIN_PAGE: Google OAuth e/o form username+password, a seconda della config.
_PASSWORD_PAGE: cambio password per gli account locali.
La variante desktop non ha login (auto-login in desktop/auth.py).
"""

_LOGIN_PAGE = '\n<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>TaskPlanner — {{ _("Accedi") }}</title>\n<style>\n:root { --bg: #f0f4f8; --card: #fff; --text: #222; --accent: #007bff; }\nbody.dark { --bg: #151821; --card: #1f2430; --text: #f5f5f5; }\n* { box-sizing: border-box; margin: 0; padding: 0; }\nbody { background: var(--bg); color: var(--text); font-family: Arial,sans-serif;\n       display: flex; align-items: center; justify-content: center; min-height: 100vh; }\n.card { background: var(--card); border-radius: 16px; padding: 48px 40px;\n        text-align: center; box-shadow: 0 4px 24px rgba(0,0,0,.15); max-width: 360px; width: 100%; }\nh1 { font-size: 1.8rem; margin-bottom: 8px; }\np { color: #666; margin-bottom: 32px; font-size: .95rem; }\n.btn-google {\n    display: inline-flex; align-items: center; gap: 12px;\n    background: #fff; border: 1px solid #ddd; border-radius: 8px;\n    padding: 12px 24px; font-size: 1rem; font-weight: 600; color: #333;\n    text-decoration: none; transition: box-shadow .2s;\n    box-shadow: 0 2px 6px rgba(0,0,0,.1);\n}\n.btn-google:hover { box-shadow: 0 4px 12px rgba(0,0,0,.2); }\n.btn-google svg { width: 22px; height: 22px; }\n.version { margin-top: 32px; font-size: .75rem; color: #aaa; }\n.login-form { display: flex; flex-direction: column; gap: 10px; text-align: left; }\n.login-form label { font-size: .85rem; font-weight: 600; }\n.login-form input { width: 100%; padding: 10px 12px; border: 1px solid #ccc; border-radius: 8px;\n                    font-size: 1rem; background: var(--card); color: var(--text); }\n.btn-primary { margin-top: 6px; background: var(--accent); color: #fff; border: 0; border-radius: 8px;\n               padding: 12px; font-size: 1rem; font-weight: 600; cursor: pointer; }\n.btn-primary:hover { filter: brightness(1.1); }\n.error { background: #fdecea; color: #b3261e; border-radius: 8px; padding: 10px 12px;\n         font-size: .88rem; margin-bottom: 16px; text-align: left; }\nbody.dark .error { background: #4a1f1f; color: #ffb4ab; }\n.separator { display: flex; align-items: center; gap: 10px; color: #999; font-size: .8rem; margin: 22px 0; }\n.separator::before, .separator::after { content: ""; flex: 1; border-top: 1px solid #ddd; }\n</style>\n</head>\n<body>\n<div class="card">\n  <h1>📋 TaskPlanner</h1>\n  {% if local_enabled and google_enabled %}\n  <p>{{ _("Accedi per continuare.") }}</p>\n  {% elif local_enabled %}\n  <p>{{ _("Accedi con il tuo username e la tua password.") }}</p>\n  {% else %}\n  <p>{{ _("Accedi con il tuo account Google per continuare.") }}</p>\n  {% endif %}\n  {% if error %}<div class="error">{{ error }}</div>{% endif %}\n  {% if local_enabled %}\n  <form class="login-form" method="post" action="/login">\n    <input type="hidden" name="csrf_token" value="{{ csrf_token }}">\n    <label for="username">{{ _("Username") }}</label>\n    <input id="username" name="username" value="{{ username }}" autocomplete="username" autocapitalize="none" required autofocus>\n    <label for="password">{{ _("Password") }}</label>\n    <input id="password" name="password" type="password" autocomplete="current-password" required>\n    <button class="btn-primary" type="submit">{{ _("Accedi") }}</button>\n  </form>\n  {% endif %}\n  {% if local_enabled and google_enabled %}<div class="separator">{{ _("oppure") }}</div>{% endif %}\n  {% if google_enabled %}\n  <a class="btn-google" href="/auth/google/login">\n    <svg viewBox="0 0 48 48"><path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/><path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/><path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/><path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/></svg>\n    {{ _("Accedi con Google") }}\n  </a>\n  {% endif %}\n  <div class="version">v{{ version }}</div>\n  <div style="margin-top:14px; font-size:.75rem; color:#aaa;"><a href="/privacy" style="color:#aaa; text-decoration:underline;">{{ _(\'Informativa privacy\') }}</a></div>\n</div>\n<script>\nif (localStorage.getItem(\'darkMode\') === \'true\') document.body.classList.add(\'dark\');\n</script>\n</body>\n</html>\n'

_PASSWORD_PAGE = '\n<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>TaskPlanner — {{ _("Cambia password") }}</title>\n<style>\n:root { --bg: #f0f4f8; --card: #fff; --text: #222; --accent: #007bff; }\nbody.dark { --bg: #151821; --card: #1f2430; --text: #f5f5f5; }\n* { box-sizing: border-box; margin: 0; padding: 0; }\nbody { background: var(--bg); color: var(--text); font-family: Arial,sans-serif;\n       display: flex; align-items: center; justify-content: center; min-height: 100vh; }\n.card { background: var(--card); border-radius: 16px; padding: 48px 40px;\n        text-align: center; box-shadow: 0 4px 24px rgba(0,0,0,.15); max-width: 360px; width: 100%; }\nh1 { font-size: 1.8rem; margin-bottom: 8px; }\np { color: #666; margin-bottom: 32px; font-size: .95rem; }\n.btn-google {\n    display: inline-flex; align-items: center; gap: 12px;\n    background: #fff; border: 1px solid #ddd; border-radius: 8px;\n    padding: 12px 24px; font-size: 1rem; font-weight: 600; color: #333;\n    text-decoration: none; transition: box-shadow .2s;\n    box-shadow: 0 2px 6px rgba(0,0,0,.1);\n}\n.btn-google:hover { box-shadow: 0 4px 12px rgba(0,0,0,.2); }\n.btn-google svg { width: 22px; height: 22px; }\n.version { margin-top: 32px; font-size: .75rem; color: #aaa; }\n.login-form { display: flex; flex-direction: column; gap: 10px; text-align: left; }\n.login-form label { font-size: .85rem; font-weight: 600; }\n.login-form input { width: 100%; padding: 10px 12px; border: 1px solid #ccc; border-radius: 8px;\n                    font-size: 1rem; background: var(--card); color: var(--text); }\n.btn-primary { margin-top: 6px; background: var(--accent); color: #fff; border: 0; border-radius: 8px;\n               padding: 12px; font-size: 1rem; font-weight: 600; cursor: pointer; }\n.btn-primary:hover { filter: brightness(1.1); }\n.error { background: #fdecea; color: #b3261e; border-radius: 8px; padding: 10px 12px;\n         font-size: .88rem; margin-bottom: 16px; text-align: left; }\nbody.dark .error { background: #4a1f1f; color: #ffb4ab; }\n.separator { display: flex; align-items: center; gap: 10px; color: #999; font-size: .8rem; margin: 22px 0; }\n.separator::before, .separator::after { content: ""; flex: 1; border-top: 1px solid #ddd; }\n</style>\n</head>\n<body>\n<div class="card">\n  <h1>🔑 {{ _("Cambia password") }}</h1>\n  {% if done %}\n  <p>{{ _("Password aggiornata.") }}</p>\n  <a class="btn-primary" style="display:block; text-decoration:none;" href="/">{{ _("Torna a TaskPlanner") }}</a>\n  {% else %}\n  {% if error %}<div class="error">{{ error }}</div>{% endif %}\n  <form class="login-form" method="post" action="/account/password">\n    <input type="hidden" name="csrf_token" value="{{ csrf_token }}">\n    <label for="current_password">{{ _("Password attuale") }}</label>\n    <input id="current_password" name="current_password" type="password" autocomplete="current-password" required autofocus>\n    <label for="new_password">{{ _("Nuova password") }}</label>\n    <input id="new_password" name="new_password" type="password" autocomplete="new-password" minlength="8" required>\n    <label for="confirm_password">{{ _("Ripeti la nuova password") }}</label>\n    <input id="confirm_password" name="confirm_password" type="password" autocomplete="new-password" minlength="8" required>\n    <button class="btn-primary" type="submit">{{ _("Salva") }}</button>\n  </form>\n  <div class="version"><a href="/" style="color:#aaa;">{{ _("Annulla") }}</a></div>\n  {% endif %}\n</div>\n<script>\nif (localStorage.getItem(\'darkMode\') === \'true\') document.body.classList.add(\'dark\');\n</script>\n</body>\n</html>\n'
